import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第二十章 占有","description":"","frontmatter":{"title":"第二十章 占有","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diwufenbian：zhanyou（diershizhang：zhanyou）.md","filePath":"blogs/CC/第五分编：占有（第二十章：占有）.md"}'),i={name:"blogs/CC/diwufenbian：zhanyou（diershizhang：zhanyou）.md"};function n(_,a,h,s,l,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="第四百五十八条" tabindex="-1">第四百五十八条 <a class="header-anchor" href="#第四百五十八条" aria-label="Permalink to &quot;第四百五十八条&quot;">​</a></h3><p>基于合同关系等产生的占有，有关不动产或者动产的使用、收益、违约责任等，按照合同约定；合同没有约定或者约定不明确的，依照有关法律规定。</p><h3 id="第四百五十九条" tabindex="-1">第四百五十九条 <a class="header-anchor" href="#第四百五十九条" aria-label="Permalink to &quot;第四百五十九条&quot;">​</a></h3><p>占有人因使用占有的不动产或者动产，致使该不动产或者动产受到损害的，恶意占有人应当承担赔偿责任。</p><h3 id="第四百六十条" tabindex="-1">第四百六十条 <a class="header-anchor" href="#第四百六十条" aria-label="Permalink to &quot;第四百六十条&quot;">​</a></h3><p>不动产或者动产被占有人占有的，权利人可以请求返还原物及其孳息；但是，应当支付善意占有人因维护该不动产或者动产支出的必要费用。</p><h3 id="第四百六十一条" tabindex="-1">第四百六十一条 <a class="header-anchor" href="#第四百六十一条" aria-label="Permalink to &quot;第四百六十一条&quot;">​</a></h3><p>占有的不动产或者动产毁损、灭失，该不动产或者动产的权利人请求赔偿的，占有人应当将因毁损、灭失取得的保险金、赔偿金或者补偿金等返还给权利人；权利人的损害未得到足够弥补的，恶意占有人还应当赔偿损失。</p><h3 id="第四百六十二条" tabindex="-1">第四百六十二条 <a class="header-anchor" href="#第四百六十二条" aria-label="Permalink to &quot;第四百六十二条&quot;">​</a></h3><p>占有的不动产或者动产被侵占的，占有人有权请求返还原物；对妨害占有的行为，占有人有权请求排除妨害或者消除危险；因侵占或者妨害造成损害的，占有人有权依法请求损害赔偿。 占有人返还原物的请求权，自侵占发生之日起一年内未行使的，该请求权消灭。</p>',10)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
